/* Monarca catalogue · local prototype data, no network requests. */
(() => {
'use strict';
const M=window.Monarca;
if(!M)return;
const {ui,products,colors,esc,icon,money,ar,photo,grid,top,btn,goto,empty,go,render,save,toast,sheet,closeSheet}=M;
const S=()=>M.state;
const norm=s=>String(s||'').toLowerCase().replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/[\u064b-\u065f]/g,'').trim();
const subsections={clothes:[['shirts','قمصان وبلوزات',2],['jackets','جاكيتات',4],['trousers','بناطيل',5],['hoodies','ملابس مريحة',3]],bags:[['shoulder','حقائب كتف',0],['tophandle','حقائب يد',0]],shoes:[['heels','أحذية بكعب',1]],accessories:[['earrings','أقراط',6]]};
const cn={all:'جميع القطع',clothes:'الملابس',bags:'الحقائب',shoes:'الأحذية',accessories:'الإكسسوارات',offers:'العروض'};
const materials={bags:'جلد طبيعي بحسب تصميم العينة؛ بطانة قماشية وإغلاق معدني. الخامة النهائية تحتاج اعتماد المورد.',shoes:'خامة علوية ناعمة مع بطانة مبطنة ونعل ثابت. هذه مواصفات توضيحية قبل اعتماد المورد.',accessories:'معدن بلون ذهبي بتفاصيل دقيقة. لا تمثل العينة ذهباً خالصاً أو شهادة مادة.',clothes:'المواصفات والخامة الموضحة بيانات تصميم تجريبية؛ تُستبدل ببطاقة المورد الفعلية قبل الإطلاق.'};
const baseMeta={1:{sub:'tophandle',detail:'مساحة لأساسيات يومك، مقبضان علويان وقفل أمامي بلون ذهبي. قطعة تعكس أسلوب Monarca الهادئ.',fabric:'جلد طبيعي · بطانة قماشية (مواصفات تجريبية)',measure:'عرض ٢٨ × ارتفاع ٢٢ × عمق ١٢ سم · قياسات توضيحية',care:'امسحيها بقطعة ناعمة وجافة. احتفظي بها داخل كيس قماشي، بعيداً عن الحرارة والرطوبة.'},2:{sub:'heels',detail:'مقدمة مدبّبة وقصّة كلاسيكية تتناسق مع البنطال أو إطلالة المساء. اختاري المقاس بعد مقارنة طول القدم.',fabric:'خامة ناعمة · نعل ثابت (مواصفات تجريبية)',measure:'ارتفاع الكعب ٨ سم · قياس توضيحي',care:'نظفي بفرشاة ناعمة وجافة. تجنبي الماء المباشر وأشعة الشمس لفترات طويلة.'},3:{sub:'shirts',detail:'ياقة كلاسيكية وأزرار أمامية مع أكمام طويلة. لون عاجي دافئ يسهل تنسيقه مع درجات البني والبيج.',fabric:'حرير ناعم بحسب تصميم العينة',measure:'قصّة عادية · طول ٦٥ سم للمقاس M (توضيحي)',care:'تنظيف متخصص بحسب ملصق القطعة. تجنبي المبيّض والحرارة العالية، واكوي على الوجه الداخلي.'},4:{sub:'hoodies',detail:'قصّة واسعة وغطاء رأس وجيب أمامي لإطلالة يومية مريحة. اختاري مقاسك المعتاد لقصّة فضفاضة.',fabric:'قطن مخلوط ناعم (مواصفات تجريبية)',measure:'قصّة واسعة · طول ٦٨ سم للمقاس M (توضيحي)',care:'غسيل لطيف على ٣٠° مع ألوان مشابهة. اقلبي القطعة قبل الغسل واتركيها تجف بشكل طبيعي.'},5:{sub:'jackets',detail:'جاكيت بقصّة محددة وحزام يبرز الخصر. جيوب أمامية وتفاصيل كلاسيكية للنهار والمساء.',fabric:'صوف مخلوط (مواصفات تجريبية)',measure:'قصّة محددة · طول ٧٢ سم للمقاس M (توضيحي)',care:'تنظيف جاف متخصص. علّقي القطعة على علاقة عريضة واحفظيها في مكان جيد التهوية.'},6:{sub:'trousers',detail:'بنطال بخصر مرتفع ورجل واسعة تمنح حركة مريحة. نسّقيه مع القميص العاجي والحقيبة البنية.',fabric:'قماش منسوج ناعم (مواصفات تجريبية)',measure:'خصر مرتفع · طول داخلي ٧٦ سم للمقاس M (توضيحي)',care:'غسيل لطيف وفق ملصق العناية. تجنبي المجفف واكوي على حرارة منخفضة.'},7:{sub:'earrings',detail:'أقراط بتصميم متدلٍّ ولون ذهبي دافئ. لمسة خفيفة تكمل الإطلالة اليومية أو المناسبة.',fabric:'معدن بلون ذهبي؛ عينة تصميم',measure:'طول ٤ سم · قياس توضيحي',care:'أبعديها عن الماء والعطور. نظفي بقطعة قماش ناعمة واحفظي كل قطعة منفصلة.'}};
products.forEach(p=>Object.assign(p,baseMeta[p.id]||{}, {sku:'MON-'+String(p.id).padStart(4,'0'),introduced:p.id}));
// Extra catalogue entries deliberately reuse supplied reference pictures, clearly disclosed on every detail page.
const additional=[
 {id:8,base:1,name:'حقيبة كتف بإطلالة كلاسيكية',en:'The classic shoulder edit',price:395000,old:450000,colors:['brown','black'],sub:'shoulder',stock:4,badge:'اختيار الموسم'},
 {id:9,base:3,name:'قميص ساتان بقصّة ناعمة',en:'The soft satin edit',material:'ساتان بلمسة ناعمة',fabric:'قماش ساتان ناعم (مواصفات تجريبية)',price:165000,old:185000,colors:['cream','taupe'],stock:6,badge:'سعر خاص'},
 {id:10,base:6,name:'بنطال واسع للعمل واليوم',en:'The everyday tailored edit',price:275000,old:325000,colors:['cream','black'],stock:4,badge:'مختارات Monarca'},
 {id:11,base:5,name:'جاكيت بحزام لإطلالة المساء',en:'The evening jacket edit',price:295000,colors:['brown','black'],stock:3,badge:'جديد'},
 {id:12,base:2,name:'كعب كلاسيكي للمناسبات',en:'The occasion heel edit',price:225000,old:245000,colors:['cream','black'],stock:3,unavailable:'41',badge:'سعر خاص'},
 {id:13,base:4,name:'هودي يومي بقصّة واسعة',en:'The off-duty hoodie edit',price:135000,old:155000,colors:['black','olive'],stock:5,badge:'راحة يومية'},
 {id:14,base:7,name:'أقراط لمسة المساء',en:'The evening earring edit',price:85000,old:95000,colors:['gold'],stock:2,badge:'لمسة أخيرة'}
];
additional.forEach(x=>{if(!products.some(p=>p.id===x.id)){const b=products.find(p=>p.id===x.base);products.push({...b,...x,sku:'MON-'+String(x.id).padStart(4,'0'),introduced:x.id,reference:true,keywords:b.keywords+' '+x.name});}});
products.forEach(p=>{p.fulfillment=[2,5].includes(Number(p.id))?'preorder':'in_stock';p.fulfillmentSource=p.fulfillment==='preorder'?'china':'iraq';M.applyDemoPricing?.(p);});
const get=id=>products.find(p=>p.id===Number(id));
const catPhoto=(img,cls='',mode='product')=>M.photo({img,name:'صورة مرجعية للقسم'},cls,mode);
const sourceOf=p=>M.fulfillmentSource?.(p)||(p.fulfillment==='preorder'?'china':'iraq');
const sourceTitle=source=>source==='iraq'?'متوفر في العراق':source==='china'?'طلب من الصين':'جميع المنتجات';
function sourceTabs(){const source=filters().source;return `<nav class="src47-tabs" aria-label="جهة التوريد">${['all','iraq','china'].map(v=>`<button type="button" data-action="cat-source" data-value="${v}" class="${source===v?'active':''}" aria-pressed="${source===v}">${sourceTitle(v)}</button>`).join('')}</nav><p class="src47-context">${source==='iraq'?'توصيل خلال يومين تقريباً · الدفع عند الاستلام أو بالبطاقة':source==='china'?'توصيل خلال ١٥–٢٠ يوماً تقريباً · الدفع المسبق بالبطاقة فقط':'التوصيل والدفع حسب جهة التوريد'}</p>`;}
const initialFilter=()=>({sub:'all',source:'all',min:0,max:800,color:'all',size:'all',stock:false});
function filters(){ui.catalogFilter={...initialFilter(),...(ui.catalogFilter||{})};return ui.catalogFilter;}
function persist(){save();}
function historyTerms(){return S().searchHistory||[];}
function addHistory(t){if(!t)return;S().searchHistory=[t,...historyTerms().filter(x=>x!==t)].slice(0,8);persist();}
function runSearch(q){ui.query=q.trim().slice(0,80);ui.category='all';ui.catalogFilter=initialFilter();ui.sort='recommended';addHistory(ui.query);go('results');}
function chooseCategory(cat,sub='all'){ui.category=cn[cat]?cat:'all';ui.query='';ui.catalogFilter={...initialFilter(),sub};ui.sort='recommended';go('results');}
function chosenIds(){return Array.isArray(ui.wishSelected)?ui.wishSelected:[];}
function categoryButtons(cat){return (subsections[cat]||[]).map(([id,label,img])=>`<button class="cat-subtile" data-action="cat-open" data-cat="${cat}" data-sub="${id}">${catPhoto(img)}<span>${label}</span><small>${ar(products.filter(p=>p.cat===cat&&p.sub===id).length)} قطع</small></button>`).join('');}
function categoriesView(){const active=Object.hasOwn(subsections,ui.catBrowse)?ui.catBrowse:'clothes';return `<div class="cat-screen">${top('اكتشفي الأقسام',`<button class="icon-btn" data-go="search" aria-label="البحث">${icon('search')}</button>`)}<div class="cat-intro"><h2>أسلوبكِ يبدأ من هنا.</h2><p>اختاري قسماً، واكتشفي القطع التي تشبهكِ.</p></div><div class="cat-search-row"><button class="cat-search" data-go="search">${icon('search')}<span class="cat-search-label">ابحثي عن قطعة أو مجموعة</span></button><button class="cat-camera" data-go="camera" aria-label="البحث بالصورة">${icon('camera')}</button></div><nav class="cat-section-grid" aria-label="الأقسام الرئيسية">${[['clothes','clothes'],['bags','bag'],['shoes','shoes'],['accessories','accessories']].map(([c,symbol])=>`<button class="cat-section-tile${active===c?' active':''}" data-action="cat-browse" data-value="${c}" aria-pressed="${active===c}" aria-controls="cat-category-panel"><span class="cat-section-symbol">${icon(symbol)}</span><b>${cn[c]}</b><small>${ar(products.filter(p=>p.cat===c).length)} قطع</small></button>`).join('')}<button class="cat-section-tile" data-go="collection/bestsellers"><span class="cat-section-symbol">${icon('star')}</span><b>الأكثر طلباً</b><small>اكتشفي الترتيب</small></button><button class="cat-section-tile" data-action="cat-open" data-cat="offers"><span class="cat-section-symbol">${icon('tag')}</span><b>العروض</b><small>أسعار مختارة</small></button></nav><section class="cat-category-panel" id="cat-category-panel" aria-labelledby="cat-category-heading"><div class="cat-minihead"><div><h3 id="cat-category-heading">تسوّقي ${cn[active]}</h3><p>اختاري نوع القطعة</p></div><button data-action="cat-open" data-cat="${active}">عرض الكل ${icon('arrow')}</button></div><div class="cat-subgrid">${categoryButtons(active)}</div></section><div class="cat-curation"><div><h3>اختيارات تتناسق معاً</h3><p>إطلالات جاهزة للإلهام، وكل قطعة قابلة للتسوّق.</p>${goto('استكشفي التنسيقات '+icon('arrow'),'lookbook','cat-textlink')}</div>${catPhoto(0)}</div><div class="cat-shortcuts">${goto(icon('clock')+' شاهدتِها مؤخراً','recent','secondary')}${goto(icon('tag')+' العروض والمختارات','collection/offers','secondary')}</div></div>`;}
function searchView(){return `<div class="cat-screen">${top('ابحثي عن إلهامك',`<button class="icon-btn" data-go="camera" aria-label="البحث بالصورة">${icon('camera')}</button>`)}<div class="page-content"><form id="cat-search-form"><label class="sr-only" for="cat-search-input">اسم القطعة أو نوعها</label><div class="input-wrap cat-search-form">${icon('search')}<input id="cat-search-input" name="query" type="search" value="${esc(ui.query)}" placeholder="حقيبة بنية، قميص، أحذية…" maxlength="80" autocomplete="off"><button type="submit" class="icon-btn" aria-label="تنفيذ البحث">${icon('arrow')}</button></div></form><div id="cat-suggestions" class="cat-suggestions" aria-live="polite"></div>${historyTerms().length?`<div class="cat-minihead"><h2>عمليات البحث الأخيرة</h2><button data-action="cat-clear-history">مسح السجل</button></div><div class="cat-chips">${historyTerms().map(t=>`<button data-action="cat-term" data-value="${esc(t)}">${icon('clock')}${esc(t)}</button>`).join('')}</div>`:''}<div class="cat-minihead"><h2>جرّبي البحث عن</h2><small>THE SEARCH EDIT</small></div><div class="cat-chips">${['حقيبة','قميص','جاكيت','كعب','أقراط','بني'].map(t=>`<button data-action="cat-term" data-value="${t}">${t}${icon('arrow')}</button>`).join('')}</div><button class="cat-photo-callout" data-go="camera">${icon('camera')}<span><b>قطعة أعجبتك في صورة؟</b><small>التقطي أو ارفعي صورة لاكتشاف قطع مشابهة.</small></span>${icon('arrow')}</button><div class="cat-minihead"><h2>تصفّحي حسب القسم</h2></div><div class="cat-search-categories">${Object.keys(subsections).map(c=>`<button data-action="cat-open" data-cat="${c}">${catPhoto(subsections[c][0][2],'','category')}<span>${cn[c]}</span></button>`).join('')}</div>${goto('مشاهدة جميع القطع','collection/all','secondary')}</div></div>`;}
function searchMatches(p,q){if(!q)return true;const full=norm([p.name,p.keywords,p.material,p.en,cn[p.cat],p.colors.map(c=>colors[c]?.[0]).join(' ')].join(' '));return q.split(/\s+/).every(w=>full.includes(w));}
function filteredProducts(){const f=filters(),q=norm(ui.query);let ps=products.filter(p=>(ui.category==='all'||!ui.category||p.cat===ui.category||(ui.category==='offers'&&p.old))&&(f.sub==='all'||p.sub===f.sub)&&p.price>=Number(f.min||0)&&p.price<=Number(f.max??800)&&(f.source==='all'||sourceOf(p)===f.source)&&(f.color==='all'||p.colors.includes(f.color))&&(f.size==='all'||p.sizes.includes(f.size)&&p.unavailable!==f.size)&&(!f.stock||(p.stock>0&&sourceOf(p)==='iraq'))&&searchMatches(p,q));if(ui.sort==='low')ps.sort((a,b)=>a.price-b.price);if(ui.sort==='high')ps.sort((a,b)=>b.price-a.price);if(ui.sort==='new')ps.sort((a,b)=>b.introduced-a.introduced);if(ui.sort==='saving')ps.sort((a,b)=>((b.old||b.price)-b.price)/(b.old||b.price)-((a.old||a.price)-a.price)/(a.old||a.price));return ps;}
function filterCount(){const f=filters();return Object.keys(f).filter(k=>k==='source'?false:k==='stock'?f.stock:k==='min'?Number(f.min)>0:k==='max'?Number(f.max)<800:f[k]!=='all').length;}
function filterTags(){const f=filters(),allsubs=Object.values(subsections).flat();return [['sub',f.sub==='all'?'':allsubs.find(r=>r[0]===f.sub)?.[1]],['color',f.color==='all'?'':colors[f.color]?.[0]],['size',f.size==='all'?'':'المقاس '+f.size],['min',f.min>0?'من '+money(f.min):''],['max',f.max<800?'حتى '+money(f.max):''],['stock',f.stock?'المتوفر فقط':'']].filter(x=>x[1]);}
function resultsView(){const ps=filteredProducts(),f=filters(),title=ui.query?`نتائج «${esc(ui.query)}»`:(ui.category==='all'?sourceTitle(f.source):cn[ui.category])||cn.all;return `<div class="cat-screen cat-results">${top(title,`<button class="icon-btn" data-go="search" aria-label="تعديل البحث">${icon('search')}</button>`)}${sourceTabs()}<div class="cat-result-summary"><p>${ui.query?'وجدنا لكِ هذه القطع':'قطع منتقاة لتعكس أسلوبك'}</p><span>${ar(ps.length)} قطعة</span></div><div class="cat-result-tabs" aria-label="تصفية حسب القسم">${['all','clothes','bags','shoes','accessories','offers'].map(c=>`<button data-action="cat-result-category" data-value="${c}" class="${ui.category===c?'active':''}">${cn[c]}</button>`).join('')}</div><div class="cat-results-toolbar"><button data-action="cat-filter">${icon('filter')} التصفية ${filterCount()?`<i>${ar(filterCount())}</i>`:''}</button><label>${icon('chevron')}<select id="cat-sort" aria-label="ترتيب المنتجات">${[['recommended','موصى بها'],['new','الأحدث'],['low','السعر: الأقل أولاً'],['high','السعر: الأعلى أولاً'],['saving','أكبر توفير']].map(([v,l])=>`<option value="${v}" ${ui.sort===v?'selected':''}>${l}</option>`).join('')}</select></label></div>${filterTags().length?`<div class="cat-active-filters">${filterTags().map(([k,l])=>`<button data-action="cat-remove-filter" data-key="${k}">${esc(l)}${icon('close')}</button>`).join('')}<button class="clear" data-action="cat-reset">مسح الكل</button></div>`:''}${ps.length?grid(ps):`<div class="cat-no-results">${icon('search')}<h2>لم نعثر على قطعة مطابقة</h2><p>جرّبي تخفيف التصفية أو استخدام كلمة أقصر مثل «حقيبة» أو «قميص».</p>${btn('مسح التصفية والبحث','cat-clear-search')}${goto('البحث بكلمات أخرى','search','secondary')}</div>`}<div class="cat-end-note">${icon('check')} ${ps.length?'وصلتِ إلى نهاية هذه المجموعة':'يمكنك أيضاً البحث بالصورة'}${!ps.length?goto('البحث بالصورة','camera','cat-textlink'):''}</div><div class="cat-footer-note">مجموعة عرض توضيحية · صور من مرجع العميل، وصور عرض مولّدة بالذكاء الاصطناعي للأحذية والأقراط.<br>الأسعار والمخزون والعروض بيانات لاختبار التجربة.</div></div>`;}
function filterSheet(){const f=filters(),subs=ui.category&&subsections[ui.category]?subsections[ui.category]:Object.values(subsections).flat();sheet('صمّمي اختياراتك',`<form id="cat-filter-form" class="cat-filter-form"><p>اختاري ما يناسبك، ثم اعرضي النتائج.</p><div class="field-row"><label class="field"><span>القسم</span><select name="category" id="cat-filter-category">${Object.keys(cn).map(c=>`<option value="${c}" ${ui.category===c?'selected':''}>${cn[c]}</option>`).join('')}</select></label><label class="field"><span>نوع القطعة</span><select name="sub" id="cat-filter-sub"><option value="all">الكل</option>${subs.map(([v,l])=>`<option value="${v}" ${f.sub===v?'selected':''}>${l}</option>`).join('')}</select></label></div><h3>نطاق السعر بالدولار الأمريكي</h3><div class="field-row"><label class="field"><span>من</span><input name="min" type="number" min="0" max="800" step="0.01" inputmode="decimal" value="${Number(f.min)}" required></label><label class="field"><span>إلى</span><input name="max" type="number" min="0" max="800" step="0.01" inputmode="decimal" value="${Number(f.max)}" required></label></div><label class="field"><span>اللون</span><select name="color"><option value="all">كل الألوان</option>${Object.entries(colors).map(([v,[l]])=>`<option value="${v}" ${f.color===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>المقاس المتوفر</span><select name="size"><option value="all">كل المقاسات</option>${['S','M','L','XL','37','38','39','40','41','مقاس موحّد'].map(v=>`<option value="${v}" ${f.size===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="cat-checkbox"><input type="checkbox" name="stock" ${f.stock?'checked':''}> عرض القطع المتوفرة في العراق فقط</label><p id="cat-filter-error" class="form-error" role="alert"></p><div class="button-stack"><button type="submit" class="primary">عرض النتائج ${icon('arrow')}</button>${btn('إعادة ضبط التصفية','cat-reset-sheet','secondary')}</div></form>`);}
function initProduct(p){if(ui.productId!==p.id){ui.productId=p.id;ui.selectedColor=p.colors[0];ui.selectedSize=p.sizes.length===1?p.sizes[0]:'';ui.productQty=1;ui.pdGallery='full';ui.pdDetails={};}if(!p.colors.includes(ui.selectedColor))ui.selectedColor=p.colors[0];if(!p.sizes.includes(ui.selectedSize)||ui.selectedSize===p.unavailable)ui.selectedSize=p.sizes.length===1?p.sizes[0]:'';ui.productQty=Math.max(1,Math.min(p.stock,Number(ui.productQty)||1));const recent=S().recentlyViewed||[];if(recent[0]!==p.id){S().recentlyViewed=[p.id,...recent.filter(id=>id!==p.id)].slice(0,16);persist();}}
function sampleReviews(id){return [{id:'demo-'+id+'-1',productId:id,name:'مراجعة توضيحية ١',stars:5,title:'مثال على تقييم القصّة',body:'هذه مراجعة تجريبية لعرض طريقة قراءة التقييمات. مساحة مناسبة لوصف المقاس والخامة وتجربة الاستخدام.',fit:'true',date:'بيانات عرض',sample:true,helpful:2},{id:'demo-'+id+'-2',productId:id,name:'مراجعة توضيحية ٢',stars:4,title:'مثال على ملاحظة عن اللون',body:'نص توضيحي يبيّن كيف تظهر ملاحظات المشترين. لا يمثل تجربة شراء فعلية أو رأياً موثّقاً.',fit:'small',date:'بيانات عرض',sample:true,helpful:1},{id:'demo-'+id+'-3',productId:id,name:'مراجعة توضيحية ٣',stars:3,title:'مثال على تقييم مختلف',body:'نموذج محايد لتجربة فرز التقييمات والاطلاع على التفاصيل. يعتمد المحتوى الحقيقي بعد الإطلاق.',fit:'large',date:'بيانات عرض',sample:true,helpful:0}];}
function allReviews(id){return [...(S().catalogReviews||[]).filter(r=>r.productId===id),...sampleReviews(id)];}
function stars(n){return `<span class="rv-stars" aria-label="${n} من 5">${Array.from({length:5},(_,i)=>`<span class="${i<n?'on':''}">★</span>`).join('')}</span>`;}
function reviewCard(r){const liked=(S().helpfulReviews||[]).includes(r.id);return `<article class="rv-card"><div class="inline-row"><b ${r.sample?'':'data-user-text'}>${esc(r.name)}</b><small class="rv-demo">${r.sample?'مثال توضيحي':'تقييم محلي · تجريبي'}</small></div><div class="inline-row">${stars(r.stars)}<small>${esc(r.date)}</small></div><h3 ${r.sample?'':'data-user-text'}>${esc(r.title)}</h3><p ${r.sample?'':'data-user-text'}>${esc(r.body)}</p>${r.fit?`<small class="rv-fit">المقاس: ${{true:'مناسب',small:'أصغر قليلاً',large:'أوسع قليلاً'}[r.fit]||'مناسب'}</small>`:''}<button class="rv-helpful ${liked?'active':''}" data-action="rv-helpful" data-id="${esc(r.id)}" aria-pressed="${liked}">${icon('check')} مفيد (${ar((r.helpful||0)+(liked?1:0))})</button></article>`;}
const isAiPhoto=p=>[1,6].includes(Number(p?.img));
function detailDisclosure(p){const source=isAiPhoto(p)?'صورة عرض عالية الدقة مولّدة بالذكاء الاصطناعي بالاستناد إلى مرجع التصميم، وليست تصويراً لمنتج فعلي موثّق. تُعتمد صور المورد وتفاصيل المنتج قبل البيع.':'الصورة مأخوذة من مرجع العميل. قد تختلف تفاصيل الخامة واللون في المنتج النهائي؛ تُعتمد صور المورد قبل البيع.';return source+(p.reference?' تُستخدم صورة العرض نفسها لقطعة أخرى من المجموعة لتوضيح التشكيلة التجريبية. اللون البديل موضح بالعينة فقط.':'');}
function detailsBlock(p,key,title,body){return `<button class="pd-disclosure" data-action="pd-disclosure" data-value="${key}" aria-expanded="${!!ui.pdDetails?.[key]}"><span>${title}</span>${icon(ui.pdDetails?.[key]?'minus':'plus')}</button>${ui.pdDetails?.[key]?`<div class="pd-disclosure-body">${body}</div>`:''}`;}
function productView(id){const p=get(id);if(!p)return `${top('القطعة غير موجودة')}${empty('هذه القطعة غير متاحة','يمكنك العودة لاكتشاف المجموعة.','bag','اكتشفي القطع','collection/all')}`;initProduct(p);const isDetail=ui.pdGallery==='detail',rs=allReviews(p.id),mean=(rs.reduce((n,r)=>n+r.stars,0)/rs.length).toFixed(1);return `<div class="cat-screen pd-screen">${top('تفاصيل القطعة',`<button class="icon-btn" data-action="pd-share" data-id="${p.id}" aria-label="مشاركة القطعة">${icon('upload')}</button>`)}<div class="pd-stage ${isDetail?'detail':''}"><button class="pd-photo-button" data-action="pd-zoom" aria-label="تكبير ${esc(p.name)}">${photo(p)}<span class="pd-zoom-hint">${icon('eye')} ${isDetail?'تفصيل مكبّر من الصورة':'اضغطي للتكبير'}</span></button><button class="favorite-btn ${S().wish.includes(p.id)?'saved':''}" data-action="wish" data-id="${p.id}" aria-label="${S().wish.includes(p.id)?'إزالة من المفضلة':'إضافة إلى المفضلة'}" aria-pressed="${S().wish.includes(p.id)}">${icon('heart')}</button><span class="pd-photo-count">${isDetail?'٢':'١'} / ٢</span></div><div class="pd-thumbnails"><button data-action="pd-gallery" data-value="full" class="${!isDetail?'active':''}" aria-pressed="${!isDetail}">${photo(p)}<span>القطعة</span></button><button data-action="pd-gallery" data-value="detail" class="${isDetail?'active':''}" aria-pressed="${isDetail}"><div class="pd-thumb-crop">${photo(p)}</div><span>تفصيل الصورة</span></button><p>عرض كامل + قصّة مكبّرة<br>لنفس صورة العرض.</p></div><div class="pd-content"><div class="pd-kicker"><small>${esc(p.en.toUpperCase())}</small><span>${p.old?'سعر خاص':p.badge||'مختارات الموسم'}</span></div><h1>${p.name}</h1>${M.fulfillmentBadge(p)}<p class="pd-material">${p.material}</p><div class="pd-price-row"><div class="price">${money(p.price)}${p.old?`<del>${money(p.old)}</del>`:''}</div>${p.old?`<small>وفّري ${ar(Math.round((1-p.price/p.old)*100))}٪</small>`:''}</div><button class="pd-review-link" data-go="reviews/${p.id}">${stars(Math.round(Number(mean)))}<span>${mean} · ${ar(rs.length)} تقييمات توضيحية ${icon('arrow')}</span></button><div class="pd-rule"></div><div class="pd-option-title"><b>اللون: ${colors[ui.selectedColor]?.[0]||''}</b><span>${ar(p.colors.length)} ${p.colors.length===1?'لون':'ألوان'}</span></div><div class="pd-colors">${p.colors.map(c=>`<button data-action="pd-color" data-value="${c}" class="${ui.selectedColor===c?'active':''}" aria-pressed="${ui.selectedColor===c}"><i style="--pd-color:${colors[c][1]}"></i><span>${colors[c][0]}</span></button>`).join('')}</div>${p.colors.length>1?'<p class="pd-subnote">الصور للون المرجعي؛ الألوان الأخرى موضحة بعينة اللون.</p>':''}<div class="pd-option-title"><b>المقاس: ${ui.selectedSize?esc(ui.selectedSize):'<em>اختاري المقاس</em>'}</b><button data-go="size-guide/${p.id}">دليل المقاسات</button></div><div class="pd-sizes">${p.sizes.map(s=>`<button data-action="pd-size" data-value="${esc(s)}" class="${ui.selectedSize===s?'active':''} ${p.unavailable===s?'unavailable':''}" aria-pressed="${ui.selectedSize===s}" ${p.unavailable===s?'aria-label="'+s+' غير متوفر؛ طلب تنبيه"':''}>${s}${p.unavailable===s?`<span>${icon('bell')}</span>`:''}</button>`).join('')}</div>${p.unavailable?`<button class="pd-stock-alert" data-action="pd-alert" data-id="${p.id}" data-size="${esc(p.unavailable)}">${icon('bell')} مقاسكِ غير متوفر؟ احفظي طلب تنبيه</button>`:''}<div class="pd-quantity-line"><span><b>الكمية</b><small>${ar(p.stock)} قطع متاحة في بيانات العرض</small></span><div class="pd-stepper" dir="ltr"><button data-action="pd-qty" data-value="-1" aria-label="تقليل الكمية" ${ui.productQty<=1?'disabled':''}>${icon('minus')}</button><output>${ar(ui.productQty)}</output><button data-action="pd-qty" data-value="1" aria-label="زيادة الكمية" ${ui.productQty>=p.stock?'disabled':''}>${icon('plus')}</button></div></div><div class="pd-delivery"><button data-action="delivery">${icon('pin')}<span>التوصيل إلى <b>${esc(ui.deliveryCity||S().address?.city||'بغداد')}</b><small>اختاري المدينة لتجربة التوصيل</small></span>${icon('chevron')}</button><p>${icon('truck')} ${sourceOf(p)==='china'?'طلب من الصين · توصيل خلال ١٥–٢٠ يوماً تقريباً':'متوفر في العراق · توصيل خلال يومين تقريباً'}</p><p>${icon('return')} استبدال وإرجاع وفق سياسة المتجر المعتمدة</p><p>${icon('card')} ${sourceOf(p)==='iraq'?'الدفع عند الاستلام أو بالبطاقة':'الدفع المسبق بالبطاقة فقط'}</p></div>${detailsBlock(p,'description','عن القطعة',`<p>${p.detail}</p><dl><div><dt>رمز القطعة</dt><dd dir="ltr">${p.sku}</dd></div><div><dt>القسم</dt><dd>${cn[p.cat]}</dd></div><div><dt>القصّة / الأبعاد</dt><dd>${p.measure}</dd></div></dl>`)}${detailsBlock(p,'material','الخامة والعناية',`<p>${p.fabric}</p><p>${materials[p.cat]}</p><p>${p.care}</p>`)}${detailsBlock(p,'delivery','التوصيل والاستبدال',`<p>رسوم التوصيل التجريبية ٤ دولارات، ومجاناً للطلبات من ٧٥ دولاراً قبل الخصم. المتوفر في العراق يصل خلال يومين تقريباً، والطلب من الصين خلال ١٥–٢٠ يوماً تقريباً.</p><p>تُعرض سياسة الإرجاع أثناء إتمام الطلب. بيانات السياسة والعناية والمدة تحتاج اعتماد المتجر قبل الإطلاق.</p>${goto('تفاصيل السياسة','policy','cat-textlink')}`)}${detailsBlock(p,'photo','عن صور ومعلومات المنتج',`<p>${detailDisclosure(p)}</p><p>لا توجد زوايا تصوير إضافية في هذه النسخة؛ عرض «تفصيل الصورة» هو تكبير لنفس صورة العرض.</p>`)}</div><section class="pd-section"><div class="cat-minihead"><h2>آراء عن القطعة</h2>${goto('عرض الكل '+icon('arrow'),'reviews/'+p.id,'cat-textlink')}</div><div class="pd-rating-note">تقييمات توضيحية لا تمثّل آراء عملاء حقيقيين.</div>${reviewCard(rs[0])}${goto('اكتبي تقييمك التجريبي','write-review/'+p.id,'secondary')}</section><section class="pd-section"><button class="pd-qa-link" data-go="qa/${p.id}">${icon('chat')}<span><b>لديك سؤال عن القطعة؟</b><small>اقرئي الإجابات أو أضيفي سؤالك</small></span>${icon('arrow')}</button></section><section class="pd-section pd-recommended"><div class="cat-minihead"><h2>أكملي الإطلالة</h2>${goto('تنسيقات الموسم','lookbook','cat-textlink')}</div>${grid(products.filter(x=>x.id!==p.id&&x.cat!==p.cat&&!x.reference).slice(0,2))}</section><div class="pd-purchase-bar">${btn(icon('bag')+' أضيفي إلى السلة','add-cart')}${btn('شراء الآن','buy-now','secondary')}</div></div>`;}
function wishlistView(){const items=products.filter(p=>S().wish.includes(p.id));const management=!!ui.wishManage;const selected=chosenIds();return `<div class="cat-screen">${top('المفضلة',items.length?btn(management?'تم':'إدارة','cat-wish-manage','cat-textlink'):'')}<div class="cat-list-intro"><small>YOUR PERSONAL EDIT</small><h2>قطع تحتفظين بها لوقتٍ جميل.</h2><p>${ar(items.length)} قطع محفوظة · اختياراتك على هذا الجهاز</p></div>${items.length?`<div class="cat-wish-toolbar">${management?`<label class="cat-checkbox"><input type="checkbox" data-cat-wish-all ${selected.length===items.length?'checked':''}> تحديد الكل (${ar(selected.length)})</label>${btn(icon('trash')+' حذف المحدد','cat-wish-remove','cat-textlink',selected.length?'':'disabled')}`:`<p>اختاري القطعة لتحديد اللون والمقاس.</p>${goto('آخر ما شاهدتِه','recent','cat-textlink')}`}</div>${management?`<div class="cat-wish-list">${items.map(p=>`<article class="cat-wish-row"><label><input type="checkbox" data-cat-wish-id="${p.id}" ${selected.includes(p.id)?'checked':''}><span class="sr-only">تحديد ${esc(p.name)}</span></label><button class="cat-wish-product" data-go="product/${p.id}">${photo(p)}<span><b>${p.name}</b><small>${cn[p.cat]} · ${p.stock>0?'متوفر':'غير متوفر'}</small>${money(p.price)}</span></button></article>`).join('')}</div>`:grid(items)}`:empty('مساحة لاختياراتك القادمة','اضغطي على القلب بجانب أي قطعة للاحتفاظ بها هنا.','heart','اكتشفي المجموعة','collection/all')}<div class="cat-footer-note">المفضلة محفوظة محلياً في النسخة التجريبية.</div></div>`;}
function recentView(){const ps=(S().recentlyViewed||[]).map(get).filter(Boolean);return `<div class="cat-screen">${top('شاهدتِها مؤخراً',ps.length?btn('مسح','cat-clear-recent','cat-textlink'):'')}<div class="cat-list-intro"><small>BACK TO SOMETHING LOVELY</small><h2>لن تفوتكِ قطعة أعجبتك.</h2><p>آخر ${ar(ps.length)} قطع زرتِها على هذا الجهاز.</p></div>${ps.length?grid(ps):empty('لم تشاهدي قطعاً بعد','تصفّحي المجموعة وستظهر هنا القطع التي تفتحينها.','clock','اكتشفي القطع','collection/all')}</div>`;}
function sizeGuideView(id){const p=get(id)||get(3);const footwear=p.cat==='shoes',one=['bags','accessories'].includes(p.cat);return `<div class="cat-screen">${top('دليل المقاسات')}<div class="page-content"><p class="overline">FIND YOUR FIT</p><h2 class="page-subtitle">اختاري المقاس بثقة.</h2><p class="page-intro">${esc(p.name)} · ${one?'مقاس موحّد':'المقاسات '+(footwear?'الأوروبية':'الدولية')}</p><div class="info-box">${icon('info')}جدول توضيحي لتجربة التصميم. تُعتمد قياسات المورد الفعلية قبل الإطلاق.</div>${one?`<div class="pd-measure-card">${photo(p)}<h3>مقاس موحّد</h3><p>${p.measure}</p></div>`:`<div class="cat-size-scroll"><table class="mini-table pd-size-table"><caption>${footwear?'قارني طول قدمك':'قياسات الجسم التقريبية'} · بالسنتيمتر</caption><thead><tr>${(footwear?['EU','طول القدم','عرض تقريبي']:['المقاس','الصدر','الخصر','الأرداف']).map(v=>`<th scope="col">${v}</th>`).join('')}</tr></thead><tbody>${(footwear?[['37','23.5','8.5'],['38','24','8.7'],['39','24.5','8.9'],['40','25','9.1'],['41','25.5','9.3']]:[['S','88–92','68–72','94–98'],['M','92–96','72–76','98–102'],['L','96–102','76–82','102–108'],['XL','102–108','82–88','108–114']]).map(row=>`<tr>${row.map((v,i)=>`<${i?'td':'th scope="row"'} dir="ltr">${v}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div><h3 class="pd-guide-title">كيف تأخذين القياس؟</h3><ol class="pd-measure-steps">${(footwear?['ضعي قدمك على ورقة وقفي باستقامة.','علّمي موضع الكعب وأطول إصبع.','قيسي المسافة وقارنيها بالجدول؛ قيسي القدمين وخذي الأكبر.']:['الصدر: مرّري الشريط حول أعرض نقطة دون شدّه.','الخصر: قيسي حول أضيق جزء من الخصر.','الأرداف: قيسي حول أعرض نقطة مع الوقوف باستقامة.']).map(t=>`<li>${t}</li>`).join('')}</ol><p class="pd-subnote">بين مقاسين؟ اطلبي المساعدة قبل الشراء؛ قد تختلف القصّة بين القطع.</p>`}<div class="button-stack">${goto('العودة إلى القطعة','product/'+p.id)}${goto(icon('chat')+' اسألي عن المقاس','qa/'+p.id,'secondary')}</div></div></div>`;}
function reviewsView(id){const p=get(id)||get(1);let rs=allReviews(p.id);const all=rs,filter=ui.reviewFilter||'all';if(filter!=='all')rs=rs.filter(r=>r.stars===Number(filter));if(ui.reviewSort==='high')rs.sort((a,b)=>b.stars-a.stars);if(ui.reviewSort==='low')rs.sort((a,b)=>a.stars-b.stars);const avg=(all.reduce((s,r)=>s+r.stars,0)/all.length).toFixed(1);return `<div class="cat-screen">${top('التقييمات')}<div class="page-content"><button class="cat-linked-product" data-go="product/${p.id}">${photo(p)}<span><b>${p.name}</b><small>${money(p.price)}</small></span>${icon('arrow')}</button><div class="rv-overview"><div><b>${avg}</b>${stars(Math.round(avg))}<small>${ar(all.length)} تقييمات توضيحية</small></div><div class="rv-distribution">${[5,4,3,2,1].map(n=>`<button data-action="rv-filter" data-value="${n}" aria-label="عرض تقييمات ${n} نجوم"><span>${ar(n)} ★</span><i><b style="width:${all.filter(r=>r.stars===n).length/all.length*100}%"></b></i><small>${ar(all.filter(r=>r.stars===n).length)}</small></button>`).join('')}</div></div><div class="info-box">${icon('info')}التقييمات المعروضة أمثلة مصرح بها لاختبار الواجهة وليست مراجعات عملاء. ما تكتبينه يحفظ على هذا الجهاز فقط.</div><div class="button-stack">${goto('اكتبي تقييماً تجريبياً','write-review/'+p.id)}</div><div class="cat-chips rv-filter-chips">${[['all','الكل'],['5','٥ نجوم'],['4','٤ نجوم'],['3','٣ نجوم'],['2','نجمتان'],['1','نجمة']].map(([v,l])=>`<button class="${filter===v?'active':''}" data-action="rv-filter" data-value="${v}">${l}</button>`).join('')}</div><div class="rv-sort"><span>${ar(rs.length)} تقييم</span><select id="rv-sort" aria-label="ترتيب التقييمات">${[['recent','الأحدث'],['high','الأعلى تقييماً'],['low','الأقل تقييماً']].map(([v,l])=>`<option value="${v}" ${ui.reviewSort===v?'selected':''}>${l}</option>`).join('')}</select></div>${rs.length?rs.map(reviewCard).join(''):'<div class="cat-inline-empty">لا توجد تقييمات بهذه الدرجة. اختاري «الكل» للعودة.</div>'}</div></div>`;}
function reviewContext(id){
 const order=(S().orders||[]).find(o=>o.id===id&&o.status==='delivered');
 if(order){const ids=[...new Set(order.items.map(l=>l.id))].filter(n=>get(n));const chosen=ids.includes(Number(ui.reviewProductId))?Number(ui.reviewProductId):ids.find(n=>!(order.reviewedItems||[]).includes(n))||ids[0];ui.reviewProductId=chosen;ui.reviewOrderId=order.id;return {p:get(chosen)||get(1),order,fromOrder:true};}
 const p=get(id)||get(1),linked=(S().orders||[]).find(o=>o.status==='delivered'&&o.items.some(l=>l.id===p.id));ui.reviewOrderId=linked?.id||null;return {p,order:linked,fromOrder:false};
}
function writeReviewView(id){const {p,order,fromOrder}=reviewContext(id),draft=ui.reviewDraft?.id===p.id?ui.reviewDraft:{id:p.id,rating:5,title:'',body:'',fit:'true'};ui.reviewDraft=draft;const orderItems=order?[...new Set(order.items.map(l=>l.id))].map(get).filter(Boolean):[];return `<div class="cat-screen">${top('تقييم القطعة')}<div class="page-content"><button class="cat-linked-product" data-go="product/${p.id}">${photo(p)}<span><b>${p.name}</b><small>${order?'مرتبط بالطلب '+esc(order.id):'تجربة كتابة التقييم'}</small></span></button><h2 class="page-subtitle">كيف كانت تجربتك؟</h2><p class="page-intro">ساعدينا في اختبار نموذج التقييم. لن يُنشر أي محتوى خارج هذا الجهاز.</p><form id="rv-write-form" data-id="${p.id}" data-order="${order?esc(order.id):''}"><input type="hidden" name="productId" value="${p.id}">${fromOrder&&orderItems.length>1?`<label class="field"><span>اختاري قطعة من الطلب المستلم</span><select id="rv-order-item" name="orderProduct">${orderItems.map(x=>`<option value="${x.id}" ${p.id===x.id?'selected':''}>${x.name}${(order.reviewedItems||[]).includes(x.id)?' · سبق تقييمها':''}</option>`).join('')}</select></label>`:''}${order?`<div class="info-box">${icon('box')}الطلب المستلم <span dir="ltr">${esc(order.id)}</span> · ${(order.reviewedItems||[]).includes(p.id)?'يمكنك إضافة تقييم تجريبي آخر لهذه القطعة.':'سيظهر حفظ التقييم في تفاصيل الطلب.'}</div>`:''}<fieldset class="rv-rating-picker"><legend>تقييمك العام</legend>${[1,2,3,4,5].map(n=>`<label class="${n<=draft.rating?'active':''}"><input type="radio" name="rating" value="${n}" ${n===Number(draft.rating)?'checked':''} required><span>★</span><small>${ar(n)}</small></label>`).join('')}</fieldset><label class="field"><span>كيف كان المقاس؟</span><select name="fit"><option value="true" ${draft.fit==='true'?'selected':''}>مناسب للمقاس المعتاد</option><option value="small" ${draft.fit==='small'?'selected':''}>أصغر قليلاً</option><option value="large" ${draft.fit==='large'?'selected':''}>أوسع قليلاً</option></select></label><label class="field"><span>عنوان التقييم</span><input name="title" maxlength="60" minlength="3" value="${esc(draft.title)}" placeholder="أبرز ما أحببتِه في القطعة" required></label><label class="field"><span>تفاصيل التقييم</span><textarea name="body" minlength="15" maxlength="500" rows="5" placeholder="الخامة، القصّة، اللون، وطريقة التنسيق…" required>${esc(draft.body)}</textarea><small class="field-note">من ١٥ إلى ٥٠٠ حرف. لا تضيفي بيانات شخصية.</small></label><label class="cat-checkbox"><input name="confirm" type="checkbox" required> أفهم أن هذا تقييم تجريبي محفوظ محلياً.</label><p id="rv-form-error" class="form-error" role="alert"></p><div class="button-stack"><button class="primary" type="submit">حفظ التقييم التجريبي</button>${goto('العودة إلى التقييمات','reviews/'+p.id,'secondary')}</div></form></div></div>`;}
function questionsView(id){const p=get(id)||get(1),qs=(S().catalogQuestions||[]).filter(q=>q.productId===p.id);return `<div class="cat-screen">${top('أسئلة عن القطعة')}<div class="page-content"><button class="cat-linked-product" data-go="product/${p.id}">${photo(p)}<span><b>${p.name}</b><small>نساعدكِ على الاختيار</small></span>${icon('arrow')}</button><h2 class="page-subtitle">التفاصيل تصنع الفرق.</h2><article class="pd-question"><span class="rv-demo">سؤال وإجابة توضيحيان</span><h3>كيف أختار المقاس المناسب؟</h3><p>قارني قياساتك بجدول القطعة، ثم تواصلي مع خدمة العملاء عند التردد. الجداول الحالية للعرض وتحتاج اعتماد المورد.</p>${goto('افتحي دليل المقاسات','size-guide/'+p.id,'cat-textlink')}</article><article class="pd-question"><span class="rv-demo">سؤال وإجابة توضيحيان</span><h3>هل اللون مطابق للصورة؟</h3><p>قد يختلف اللون باختلاف الشاشة والإضاءة. ${isAiPhoto(p)?'صورة هذه القطعة مولّدة بالذكاء الاصطناعي لعرض النموذج، وليست تصويراً لمنتج فعلي موثّق.':'صورة هذه القطعة من مرجع العميل.'} الألوان الإضافية ممثلة بعينات لونية، وتُعتمد صور المورد قبل البيع.</p></article>${qs.map(q=>`<article class="pd-question"><span class="rv-demo">سؤالك · محفوظ محلياً</span><h3>${esc(q.text)}</h3><p>تم تسجيل السؤال في النموذج التجريبي. لا يتم إرساله إلى فريق خدمة عملاء حقيقي.</p><small>بانتظار الإجابة في تجربة العرض</small></article>`).join('')}<form id="pd-question-form" data-id="${p.id}" class="pd-question-form"><label class="field"><span>اسألي عن هذه القطعة</span><textarea name="question" minlength="8" maxlength="300" placeholder="اكتبي سؤالك عن الخامة أو المقاس أو تفاصيل القطعة…" required></textarea></label><button class="primary" type="submit">تسجيل السؤال التجريبي ${icon('send')}</button><p class="pd-subnote">السؤال محفوظ على هذا الجهاز. لخدمة العملاء: افتحي المساعدة.</p></form>${goto('التواصل مع المساعدة','support','secondary')}</div></div>`;}
function collectionView(id){if(['iraq','china'].includes(id)){if(ui.catalogCollection!==id){ui.catalogCollection=id;ui.category='all';ui.query='';ui.catalogFilter={...initialFilter(),source:id};ui.sort='recommended';}return resultsView();}if(id==='bestsellers'){const rows=M.bestSellerStats?.()||[];return `<div class="cat-screen">${top('الأكثر طلباً')}<div class="cat-bestseller-intro"><h2>القطع الأكثر اختياراً</h2><p>ترتيب توضيحي من طلبات النسخة التجريبية</p><small>بحسب عدد القطع في الطلبات المؤكدة غير الملغاة على هذا الجهاز، وتشمل الدفع عند الاستلام. هذا ليس إحصاءً حقيقياً لكل مستخدمات المتجر.</small></div>${rows.length?M.bestSellerGrid(rows):empty('لا يوجد ترتيب بعد','يظهر هنا ترتيب القطع عند تأكيد طلب في النسخة التجريبية.','bag','اكتشفي المجموعة','collection/all')}<div class="page-content cat-bestseller-footer">${goto('تصفّحي جميع القطع','collection/all','secondary')}</div></div>`;}const key=cn[id]?id:'all';if(ui.catalogCollection!==key){ui.catalogCollection=key;ui.category=key;ui.query='';ui.catalogFilter=initialFilter();ui.sort='recommended';}return resultsView();}
function lookbookView(){const ids=ui.lookbook==='weekend'?[4,6,1,7]:ui.lookbook==='evening'?[5,2,1,7]:[3,6,1,2],ps=ids.map(get);return `<div class="cat-screen">${top('تنسيقات Monarca')}<div class="cat-list-intro"><small>THOUGHTFULLY TOGETHER</small><h2>إطلالة متكاملة، بطريقتكِ.</h2><p>إلهام للتنسيق من المجموعة التجريبية.</p></div><div class="cat-chips cat-look-tabs">${[['everyday','أناقة كل يوم'],['evening','للمساء'],['weekend','وقت الراحة']].map(([v,l])=>`<button class="${(ui.lookbook||'everyday')===v?'active':''}" data-action="cat-lookbook" data-value="${v}">${l}</button>`).join('')}</div><div class="cat-look-collage">${ps.map((p,i)=>`<button data-go="product/${p.id}" class="look-${i}">${photo(p)}<span>${ar(i+1)}</span></button>`).join('')}</div><div class="page-content"><div class="cat-minihead"><h2>تسوّقي قطع الإطلالة</h2><small>${ar(ps.length)} قطع</small></div>${ps.map((p,i)=>`<button class="cat-linked-product" data-go="product/${p.id}"><i>${ar(i+1)}</i>${photo(p)}<span><b>${p.name}</b><small>${money(p.price)}</small></span>${icon('plus')}</button>`).join('')}<div class="cat-look-total"><span>إجمالي القطع المعروضة</span><b>${money(ps.reduce((s,p)=>s+p.price,0))}</b></div><p class="pd-subnote">اختاري كل قطعة لتحديد المقاس واللون قبل الإضافة. الأسعار والمواصفات بيانات عرض.</p>${goto('اكتشفي جميع القطع','collection/all','secondary')}</div></div>`;}
function stockAlert(p,size){const existing=(S().stockAlerts||[]).some(a=>a.productId===p.id&&a.size===size);sheet('تنبيه توفر المقاس',`<div class="cat-linked-product">${photo(p)}<span><b>${p.name}</b><small>المقاس ${esc(size)} · ${colors[ui.selectedColor||p.colors[0]][0]}</small></span></div><p>${existing?'يوجد طلب تنبيه محفوظ لهذا المقاس. يمكنك تحديث رقم التواصل.':'احفظي رقم التواصل لتجربة الاشتراك في تنبيه التوفر.'}</p><form id="pd-alert-form" data-id="${p.id}" data-size="${esc(size)}" style="margin-top:18px"><label class="field"><span>رقم الهاتف العراقي</span><input type="tel" name="phone" inputmode="tel" dir="ltr" placeholder="0770 000 0000" value="${esc(S().user?.phone||S().address?.phone||'')}" required></label><p id="pd-alert-error" class="form-error" role="alert"></p><p class="pd-subnote">تجربة محلية فقط؛ لن تُرسل رسالة SMS أو إشعار حقيقي.</p><div class="button-stack"><button class="primary" type="submit">حفظ طلب التنبيه</button></div></form>`);}
function shareProduct(p){const url='https://itsmonarca.com/#product/'+p.id;sheet('مشاركة القطعة',`<div class="cat-linked-product">${photo(p)}<span><b>${p.name}</b><small>${money(p.price)}</small></span></div><p>انسخي رابط القطعة لمشاركتها مع صديقاتك أو فتحها مباشرة في متجر Monarca.</p><label class="field" style="margin-top:18px"><span>رابط القطعة</span><input id="pd-share-url" class="ltr" readonly value="${esc(url)}"></label><div class="button-stack">${btn(icon('upload')+' نسخ الرابط','pd-copy','primary')}</div><p id="pd-copy-note" class="pd-subnote"></p>`);}
const actions={
 'cat-source':el=>{const value=el.dataset.value;if(!['all','iraq','china'].includes(value))return;if(ui.route.startsWith('collection/')){go('collection/'+value);return;}filters().source=value;render();},
 'cat-browse':el=>{if(!Object.hasOwn(subsections,el.dataset.value))return;ui.catBrowse=el.dataset.value;render(true);document.querySelector('.cat-section-tile[data-value="'+ui.catBrowse+'"]')?.focus({preventScroll:true});},
 'cat-open':el=>chooseCategory(el.dataset.cat,el.dataset.sub||'all'),
 'cat-term':el=>runSearch(el.dataset.value),
 'cat-clear-history':()=>{S().searchHistory=[];persist();render(true);toast('تم مسح سجل البحث');},
 'cat-result-category':el=>{ui.category=el.dataset.value;filters().sub='all';render();},
 'cat-filter':filterSheet,
 'cat-remove-filter':el=>{const k=el.dataset.key;filters()[k]=initialFilter()[k];render(true);},
 'cat-reset':()=>{ui.catalogFilter={...initialFilter(),source:filters().source};ui.sort='recommended';render(true);},
 'cat-clear-search':()=>{ui.catalogFilter={...initialFilter(),source:filters().source};ui.category='all';ui.query='';render();},
 'cat-reset-sheet':()=>{ui.catalogFilter={...initialFilter(),source:filters().source};ui.category='all';closeSheet();filterSheet();},
 'cat-wish-manage':()=>{ui.wishManage=!ui.wishManage;ui.wishSelected=[];render(true);},
 'cat-wish-remove':()=>{const ids=chosenIds();if(!ids.length)return;sheet('إزالة من المفضلة',`<p>هل تريدين إزالة ${ar(ids.length)} قطع محددة من مفضلتك؟</p><div class="button-stack">${btn('إزالة القطع المحددة','cat-wish-confirm')}${btn('الاحتفاظ بها','close-sheet','secondary')}</div>`);},
 'cat-wish-confirm':()=>{const ids=chosenIds();S().wish=S().wish.filter(id=>!ids.includes(id));ui.wishSelected=[];persist();closeSheet();render(true);toast('تم تحديث المفضلة');},
 'cat-clear-recent':()=>sheet('مسح سجل المشاهدة',`<p>هل تريدين مسح القطع التي شاهدتِها مؤخراً على هذا الجهاز؟</p><div class="button-stack">${btn('مسح السجل','cat-confirm-clear-recent')}${btn('الاحتفاظ بالسجل','close-sheet','secondary')}</div>`),
 'cat-confirm-clear-recent':()=>{S().recentlyViewed=[];persist();closeSheet();render();toast('تم مسح سجل المشاهدة');},
 'cat-lookbook':el=>{ui.lookbook=el.dataset.value;render(true);},
 'pd-color':el=>{ui.selectedColor=el.dataset.value;render(true);},
 'pd-size':el=>{const p=get(ui.productId),size=el.dataset.value;if(p.unavailable===size){stockAlert(p,size);return;}ui.selectedSize=size;render(true);},
 'pd-alert':el=>{const p=get(el.dataset.id);if(p)stockAlert(p,el.dataset.size);},
 'pd-qty':el=>{const p=get(ui.productId);ui.productQty=Math.max(1,Math.min(p.stock,(Number(ui.productQty)||1)+Number(el.dataset.value)));render(true);},
 'pd-gallery':el=>{ui.pdGallery=el.dataset.value;render(true);},
 'pd-zoom':()=>{const p=get(ui.productId);sheet('تفاصيل صورة العرض',`<div class="pd-zoom-frame ${ui.pdGallery==='detail'?'detail':''}">${photo(p)}</div><p>${ui.pdGallery==='detail'?'قصّة مكبّرة من صورة العرض نفسها؛ ليست زاوية تصوير إضافية. ':''}${isAiPhoto(p)?'صورة عرض مولّدة بالذكاء الاصطناعي بالاستناد إلى مرجع التصميم، وليست تصويراً لمنتج فعلي موثّق.':'الصورة المرجعية التي قدّمها العميل.'}</p><div class="button-stack">${btn('العودة إلى القطعة','close-sheet','secondary')}</div>`);},
 'pd-disclosure':el=>{ui.pdDetails=ui.pdDetails||{};ui.pdDetails[el.dataset.value]=!ui.pdDetails[el.dataset.value];render(true);},
 'pd-share':async el=>{const p=get(el.dataset.id);if(!p)return;const url='https://itsmonarca.com/#product/'+p.id;if(navigator.share){try{await navigator.share({title:p.name+' · Monarca',text:(p.name_ar||p.name)+' · Monarca Boutique',url:url});return;}catch(e){if(e.name==='AbortError')return;}}shareProduct(p);},
 'pd-copy':async()=>{const input=document.getElementById('pd-share-url');if(!input)return;try{if(!navigator.clipboard?.writeText)throw new Error('clipboard');await navigator.clipboard.writeText(input.value);toast('تم نسخ رابط القطعة');document.getElementById('pd-copy-note').textContent='تم النسخ. يمكنك لصقه في رسالتك.';}catch{input.focus();input.select();document.getElementById('pd-copy-note').textContent='تم تحديد الرابط. استخدمي أمر «نسخ» في جهازك لنسخه.';}},
 'rv-filter':el=>{ui.reviewFilter=el.dataset.value;render(true);},
 'rv-helpful':el=>{const id=el.dataset.id,a=S().helpfulReviews||[];S().helpfulReviews=a.includes(id)?a.filter(v=>v!==id):[...a,id];persist();render(true);}
};
const forms={
 'cat-search-form':(form,data)=>runSearch(data.query||''),
 'cat-filter-form':(form,d)=>{const min=Number(d.min),max=Number(d.max);if(!Number.isFinite(min)||!Number.isFinite(max)||min<0||max<min||max>800){const err=document.getElementById('cat-filter-error');err.textContent='يجب أن يكون الحد الأعلى أكبر من أو مساوياً للحد الأدنى، ضمن ٠–٨٠٠ دولار.';err.classList.add('visible');return;}ui.category=cn[d.category]?d.category:'all';ui.catalogFilter={sub:d.sub||'all',source:filters().source,min,max,color:d.color||'all',size:d.size||'all',stock:d.stock==='on'};closeSheet();render();},
 'rv-write-form':(form,d)=>{const p=get(d.productId||form.dataset.id),rating=Number(d.rating);if(!p||rating<1||rating>5||String(d.title).trim().length<3||String(d.body).trim().length<15||!d.confirm){const er=document.getElementById('rv-form-error');er.textContent='أكملي التقييم والعنوان والتفاصيل والموافقة لحفظ النموذج.';er.classList.add('visible');return;}const o=(S().orders||[]).find(o=>o.id===form.dataset.order&&o.status==='delivered'&&o.items.some(l=>l.id===p.id));S().catalogReviews=S().catalogReviews||[];S().catalogReviews.unshift({id:'local-'+Date.now(),productId:p.id,name:S().user?.name||'تقييمك التجريبي',stars:rating,title:d.title.trim().slice(0,60),body:d.body.trim().slice(0,500),fit:d.fit,date:'الآن · تجربة محلية',sample:false,helpful:0,orderId:o?.id||null});if(o)o.reviewedItems=[...new Set([...(o.reviewedItems||[]),p.id])];ui.reviewDraft=null;ui.reviewOrderId=null;ui.reviewProductId=null;ui.reviewFilter='all';ui.reviewSort='recent';persist();toast('تم حفظ التقييم التجريبي على هذا الجهاز');go('reviews/'+p.id);},
 'pd-question-form':(form,d)=>{const p=get(form.dataset.id),text=String(d.question||'').trim();if(!p||text.length<8){toast('اكتبي سؤالاً من ٨ أحرف على الأقل.');return;}S().catalogQuestions=S().catalogQuestions||[];S().catalogQuestions.unshift({id:Date.now(),productId:p.id,text:text.slice(0,300)});persist();render(true);toast('تم حفظ سؤالك في النسخة التجريبية');},
 'pd-alert-form':(form,d)=>{const p=get(form.dataset.id),phone=M.normalizePhone(d.phone);if(!p)return;if(!phone){const er=document.getElementById('pd-alert-error');er.textContent='أدخلي رقم هاتف عراقي صحيحاً، مثل 07700000000.';er.classList.add('visible');return;}const size=form.dataset.size;S().stockAlerts=(S().stockAlerts||[]).filter(a=>!(a.productId===p.id&&a.size===size));S().stockAlerts.push({productId:p.id,size,color:ui.selectedColor||p.colors[0],phone,status:'demo'});persist();closeSheet();toast('تم حفظ طلب التنبيه محلياً؛ لن تُرسل رسالة حقيقية');}
};
function change(e){const t=e.target;if(t.id==='cat-sort'){ui.sort=t.value;render(true);return true;}if(t.id==='rv-sort'){ui.reviewSort=t.value;render(true);return true;}if(t.id==='rv-order-item'){ui.reviewProductId=Number(t.value);ui.reviewDraft=null;render(true);return true;}if(t.id==='cat-filter-category'){const subs=t.value==='all'||t.value==='offers'?Object.values(subsections).flat():subsections[t.value]||[];document.getElementById('cat-filter-sub').innerHTML='<option value="all">الكل</option>'+subs.map(([v,l])=>`<option value="${v}">${l}</option>`).join('');return true;}if(t.matches('[data-cat-wish-id]')){const id=Number(t.dataset.catWishId);ui.wishSelected=t.checked?[...new Set([...chosenIds(),id])]:chosenIds().filter(v=>v!==id);render(true);return true;}if(t.matches('[data-cat-wish-all]')){ui.wishSelected=t.checked?[...S().wish]:[];render(true);return true;}if(t.matches('#rv-write-form input[name="rating"]')){ui.reviewDraft.rating=Number(t.value);document.querySelectorAll('.rv-rating-picker label').forEach((label,i)=>label.classList.toggle('active',i<Number(t.value)));return true;}return false;}
document.addEventListener('input',e=>{if(e.target.id==='cat-search-input'){const q=norm(e.target.value),box=document.getElementById('cat-suggestions');if(!box)return;const ps=q?products.filter(p=>searchMatches(p,q)).slice(0,4):[];box.innerHTML=q?`<small>${ps.length?'اقتراحات مطابقة':'لا توجد اقتراحات؛ جرّبي البحث بالصورة'}</small>${ps.map(p=>`<button class="cat-suggest-item" data-go="product/${p.id}">${photo(p)}<span><b>${p.name}</b><small>${money(p.price)}</small></span>${icon('arrow')}</button>`).join('')}`:'';}if(e.target.closest('#rv-write-form')&&ui.reviewDraft){const d=Object.fromEntries(new FormData(e.target.closest('form')));Object.assign(ui.reviewDraft,{title:d.title||'',body:d.body||'',fit:d.fit||'true',rating:Number(d.rating)||5});}});
M.register({routes:{categories:categoriesView,search:searchView,results:resultsView,product:productView,wishlist:wishlistView,recent:recentView,'size-guide':sizeGuideView,reviews:reviewsView,'write-review':writeReviewView,qa:questionsView,collection:collectionView,lookbook:lookbookView},actions,forms,change,onRoute:(name)=>{if(name!=='collection')ui.catalogCollection=null;}});
})();

